package.path = "./?.lua;" .. package.path

local failures = 0
local function assert_eq(actual, expected, label)
    if actual ~= expected then
        failures = failures + 1
        io.stderr:write(string.format("FAIL %s: got %q expected %q\n", label, tostring(actual), tostring(expected)))
    end
end

local Aes = require("weread.lib.aes")
local Eink = require("weread.lib.eink")

-- AES-128-CBC NIST-style smoke: encrypt with known Python vector.
do
    local key = "0123456789abcdef"
    local iv = "fedcba9876543210"
    local ct = ""
    for byte in ("52d21baf7ad5501a944d0148111e8bb0"):gmatch("..") do
        ct = ct .. string.char(tonumber(byte, 16))
    end
    assert_eq(Aes.decrypt_cbc(ct, key, iv), "hello eink aes", "aes-cbc roundtrip")
end

assert_eq(Eink.build_chapters_param({ 6 }), "6", "single chapter")
assert_eq(Eink.build_chapters_param({ 1, 2, 3, 4, 5, 6 }), "1-6", "contiguous range")
assert_eq(Eink.build_chapters_param({ 1, 2, 3, 8, 10, 11, 12 }), "1-3,8,10-12", "mixed ranges")
assert_eq(Eink.build_chapters_param({ "12", 10, 11 }), "10-12", "sorts numeric uids")

local marks = {
    { chapterUid = 4, range = "1-2", markText = "a", type = 0 },
    { chapterUid = 4, range = "3-4", markText = "b", type = 1 },
    { chapterUid = 5, range = "9-10", markText = "c", type = 0 },
}
local chapter4 = Eink.underlines_for_chapter(marks, 4)
assert_eq(#chapter4.underlines, 2, "bookmarklist filtered to chapter")
assert_eq(#Eink.underlines_for_chapter(marks, 9).underlines, 0, "empty chapter")


do
    local hex = ""
    local tar = hex:gsub("..", function(b) return string.char(tonumber(b, 16)) end)
    assert_eq(Eink.is_tar(tar) and "1" or "0", "1", "tar detected")
    local files = Eink.untar(tar)
    assert_eq(files["info.txt"], [[{"chapters":[]}]], "tar info.txt")
    assert_eq(files["Text/1.xhtml"], "<html>ok</html>", "tar xhtml")
    local tar_path = os.tmpname()
    local out_dir = tar_path .. ".d"
    os.execute("mkdir -p " .. string.format("%q", out_dir))
    local tf = io.open(tar_path, "wb")
    tf:write(tar)
    tf:close()
    local names = Eink.untar_file(tar_path, out_dir)
    local extracted = Eink.read_file(out_dir .. "/1.xhtml")
    assert_eq(extracted, "<html>ok</html>", "untar_file writes chapter to disk")
    local has_info = "0"
    for _, name in ipairs(names) do
        if name == "info.txt" then has_info = "1" end
    end
    assert_eq(has_info, "1", "untar_file lists info.txt")
    os.remove(tar_path)
    os.execute("rm -rf " .. string.format("%q", out_dir))
end

do
    local files = {
        ["info.txt"] = [[{"chapters":[]}]],
        ["9.txt"] = "chapter nine",
        ["10.txt"] = "chapter ten",
    }
    local chapters = {
        { chapterUid = 9, files = { "9.txt" } },
        { chapterUid = 10 },
    }
    local bodies = Eink.files_to_chapter_bodies(files, chapters)
    assert_eq(bodies["9"] and bodies["9"]:find("<p>chapter nine</p>", 1, true) and "1" or "0",
        "1", "txt via chapter.files")
    assert_eq(bodies["10"] and bodies["10"]:find("<p>chapter ten</p>", 1, true) and "1" or "0",
        "1", "txt via uid")
    assert_eq(bodies["info.txt"] and "1" or "0", "0", "info.txt is not a chapter")
end

do
    local files = { ["1.xhtml"] = "<html>ok</html>" }
    local chapters = { { chapterUid = 1, files = { "Text/1.xhtml" } } }
    local bodies = Eink.files_to_chapter_bodies(files, chapters)
    assert_eq(bodies["1"], "<html>ok</html>", "basename fallback for chapter.files")
end

do
    local files = {
        ["info.txt"] = [[{"chapters":[]}]],
        ["465030_1330_o"] = "chapter 1330",
        ["465030_608_o"] = "chapter 608",
    }
    local chapters = {
        { chapterUid = 1330 },
        { chapterUid = 608 },
    }
    local bodies = Eink.files_to_chapter_bodies(files, chapters)
    assert_eq(bodies["1330"] and bodies["1330"]:find("<p>chapter 1330</p>", 1, true) and "1" or "0",
        "1", "tinyfile bookId_uid_o maps 1330")
    assert_eq(bodies["608"] and bodies["608"]:find("<p>chapter 608</p>", 1, true) and "1" or "0",
        "1", "tinyfile bookId_uid_o maps 608")
    assert_eq(Eink.payload_kind(files["465030_1330_o"]):sub(1, 5), "text:", "payload kind text")
    local index = Eink.build_uid_index(files)
    assert_eq(index["1330"], "465030_1330_o", "uid index 1330")
    local one = Eink.chapter_xhtml(files, { chapterUid = 608 }, index)
    assert_eq(one and one:find("<p>chapter 608</p>", 1, true) and "1" or "0", "1", "lazy chapter xhtml")
end

do
    local xhtml = Eink.txt_to_xhtml("a < b & c")
    local expected = "<p>a " .. "&" .. "lt; b " .. "&" .. "amp; c</p>"
    assert_eq(xhtml:find(expected, 1, true) and "1" or "0", "1", "txt xml escape")
end

do
    local ideo = "\227\128\128\227\128\128"
    local xhtml = Eink.txt_to_xhtml(ideo .. "少妇见此\n  hello  \n")
    assert_eq(xhtml:find("<p>少妇见此</p>", 1, true) and "1" or "0", "1",
        "strip ideographic indent")
    assert_eq(xhtml:find("<p>hello</p>", 1, true) and "1" or "0", "1",
        "strip ascii indent")
end

if failures > 0 then
    os.exit(1)
end
print("eink_spec ok")
